const Encryption = require('./encryption.js');

const password = '.0x304dh3761ga3.';

const message = 
    `
    
    `;

const encryption = new Encryption();

const runExample = async () => {
    try {
        const decrypted = await encryption.decryptBase64(message);
        // console.log('Decrypted Base64:', decrypted);

        const decryptedXor = await encryption.decryptXor(decrypted, password);
        console.log('Decrypted XOR:', decryptedXor);
    } catch (error) {
        console.error('Error during decryption:', error);
        throw error;
    }
};

runExample().then(() => process.exit(0)).catch(() => process.exit(1));